<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import FloatingWindow from '../components/common/FloatingWindow.vue'
import NeonPanel from '../components/common/NeonPanel.vue'
import { useAppStore } from '../stores/app'
const store = useAppStore(); const workflows = ref([]); const runs = ref([]); const editor = ref(false); const runWindow = ref(false); const selected = ref(null); const validation = ref(null); const nodeDraft = reactive({ type: 'runbook', label: '', config: {} }); const draft = reactive({ id: '', name: '', description: '', nodes: [], edges: [] }); const runInputs = ref('{}')
const nodeKinds = [{ value: 'runbook', title: 'Runbook dispatch' }, { value: 'inventory-sync', title: 'Inventory sync' }, { value: 'condition', title: 'Condition' }, { value: 'parallel', title: 'Parallel join' }, { value: 'wait', title: 'Wait' }, { value: 'approval', title: 'Approval gate' }, { value: 'notification', title: 'Notification' }, { value: 'retry', title: 'Retry policy' }, { value: 'rollback', title: 'Rollback / compensation' }]
const scripts = computed(() => (store.catalog.library || []).filter((item) => item.type === 'script')); const machines = computed(() => store.catalog.machines || []); const sources = ref([])
async function refresh() { workflows.value = await store.listWorkflows(); sources.value = await store.listInventorySources() }
function open(workflow = null) { Object.assign(draft, workflow ? { id: workflow.id, name: workflow.name, description: workflow.description || '', nodes: structuredClone(workflow.graph.nodes || []), edges: structuredClone(workflow.graph.edges || []) } : { id: '', name: 'Untitled workflow', description: '', nodes: [], edges: [] }); validation.value = null; editor.value = true }
function defaultConfig(type) { return type === 'runbook' ? { scriptIds: [], machineIds: [], retryLimit: 0 } : type === 'inventory-sync' ? { sourceId: '' } : type === 'condition' ? { left: '{{inputs.approved}}', equals: 'true' } : type === 'wait' ? { seconds: 30 } : type === 'approval' ? { message: 'Workflow approval required', expiresMinutes: 60 } : type === 'notification' ? { title: 'Workflow update', summary: '', eventType: 'job.success' } : {} }
function addNode(type) { const id = `node-${Date.now()}`; draft.nodes.push({ id, type, label: nodeKinds.find((kind) => kind.value === type)?.title || type, config: defaultConfig(type) }); if (draft.nodes.length > 1) draft.edges.push({ from: draft.nodes[draft.nodes.length - 2].id, to: id }) }
function removeNode(id) { draft.nodes = draft.nodes.filter((node) => node.id !== id); draft.edges = draft.edges.filter((edge) => edge.from !== id && edge.to !== id) }
async function check() { validation.value = await store.validateWorkflow({ nodes: draft.nodes, edges: draft.edges }) }
async function save() { await check(); if (!validation.value.ok) return; const saved = await store.saveWorkflow({ id: draft.id || undefined, name: draft.name, description: draft.description, graph: { nodes: draft.nodes, edges: draft.edges }, ...store.activeScope }); editor.value = false; await refresh(); selected.value = saved }
async function openRuns(workflow) { selected.value = workflow; runs.value = await store.workflowRuns(workflow.id); runWindow.value = true }
async function run() { let inputs = {}; try { inputs = JSON.parse(runInputs.value || '{}') } catch { return }; await store.runWorkflow(selected.value.id, inputs); runs.value = await store.workflowRuns(selected.value.id) }
onMounted(refresh)
</script>
<template><div class="workflow-workspace"><div class="toolbar-row"><div><p class="section-eyebrow">Orchestrated Automation</p><h2 class="page-title">Visual Workflows</h2></div><v-btn class="glass-button" prepend-icon="mdi-graph-outline" @click="open()">New Workflow</v-btn></div><NeonPanel subtitle="DAG Templates" title="Workflow Portfolio"><div class="workflow-grid"><article v-for="workflow in workflows" :key="workflow.id" class="workflow-card"><div><p class="section-eyebrow">{{ workflow.graph.nodes.length }} nodes · {{ workflow.graph.edges.length }} paths</p><strong>{{ workflow.name }}</strong><span>{{ workflow.description || 'No description supplied.' }}</span></div><div class="chip-line"><v-btn size="small" variant="text" @click="open(workflow)">Design</v-btn><v-btn size="small" class="glass-button" @click="openRuns(workflow)">Run</v-btn></div></article><p v-if="!workflows.length" class="empty-state">Create a DAG template to combine dispatch, inventory, approval, and recovery paths.</p></div></NeonPanel><FloatingWindow v-model="editor" :title="draft.id ? 'Workflow Designer' : 'Create Workflow'" :width="1040" :start-x="105" :start-y="75"><div class="designer"><aside class="palette"><p class="section-eyebrow">Node Palette</p><v-btn v-for="kind in nodeKinds" :key="kind.value" size="small" variant="text" @click="addNode(kind.value)">{{ kind.title }}</v-btn></aside><main class="canvas"><div class="designer-head"><v-text-field v-model="draft.name" label="Workflow name" density="compact" hide-details/><v-text-field v-model="draft.description" label="Purpose" density="compact" hide-details/><v-btn size="small" variant="text" @click="check">Validate</v-btn><v-btn size="small" class="glass-button" @click="save">Save</v-btn></div><v-alert v-if="validation" :type="validation.ok ? 'success' : 'error'" density="compact" variant="tonal">{{ validation.ok ? 'Graph is valid and acyclic.' : validation.errors.join(' · ') }}</v-alert><article v-for="node in draft.nodes" :key="node.id" class="flow-node"><header><v-chip size="x-small" color="secondary">{{ node.type }}</v-chip><v-text-field v-model="node.label" density="compact" hide-details/><v-btn size="x-small" icon="mdi-close" variant="text" @click="removeNode(node.id)"/></header><div v-if="node.type === 'runbook'" class="node-fields"><v-select v-model="node.config.scriptIds" :items="scripts" item-title="name" item-value="id" label="Runbooks" multiple chips density="compact"/><v-select v-model="node.config.machineIds" :items="machines" item-title="name" item-value="id" label="Targets" multiple chips density="compact"/><v-text-field v-model.number="node.config.retryLimit" type="number" label="Retries" density="compact"/></div><div v-else-if="node.type === 'inventory-sync'" class="node-fields"><v-select v-model="node.config.sourceId" :items="sources" item-title="name" item-value="id" label="Managed inventory source" density="compact"/></div><div v-else-if="node.type === 'condition'" class="node-fields"><v-text-field v-model="node.config.left" label="Left value / {{inputs.key}}" density="compact"/><v-text-field v-model="node.config.equals" label="Equals" density="compact"/></div><div v-else-if="node.type === 'wait'" class="node-fields"><v-text-field v-model.number="node.config.seconds" type="number" min="0" label="Wait seconds" density="compact"/></div><div v-else-if="node.type === 'approval'" class="node-fields"><v-text-field v-model="node.config.message" label="Approval message" density="compact"/><v-text-field v-model.number="node.config.expiresMinutes" type="number" min="1" label="Expires after minutes" density="compact"/></div><div v-else-if="node.type === 'notification'" class="node-fields"><v-text-field v-model="node.config.title" label="Notification title" density="compact"/><v-text-field v-model="node.config.summary" label="Summary" density="compact"/></div><small v-else>Control node: it preserves orchestration intent and execution evidence in the run ledger.</small></article></main></div></FloatingWindow><FloatingWindow v-model="runWindow" :title="`Run: ${selected?.name || ''}`" :width="720" :start-x="310" :start-y="110"><div class="run-panel"><v-textarea v-model="runInputs" label="Workflow inputs (JSON)" rows="3"/><v-btn class="glass-button" @click="run">Start workflow run</v-btn><article v-for="run in runs" :key="run.id" class="run-card"><div><strong>{{ run.status }}</strong><span class="mono">{{ run.started_at }}</span></div><p v-if="run.error_message">{{ run.error_message }}</p><div class="node-run-list"><span v-for="node in run.nodes" :key="node.id">{{ node.node_id }}: {{ node.status }}</span></div></article></div></FloatingWindow></div></template>
<style scoped>.workflow-workspace,.workflow-grid,.designer,.run-panel{display:grid;gap:14px}.workflow-grid{grid-template-columns:repeat(auto-fit,minmax(280px,1fr));padding:14px}.workflow-card{display:flex;justify-content:space-between;gap:12px;padding:14px;border:1px solid var(--line);background:linear-gradient(135deg,rgba(40,211,255,.07),rgba(190,77,255,.06))}.workflow-card div:first-child{display:grid;gap:5px}.workflow-card p,.workflow-card span,.empty-state{margin:0;color:var(--muted);font-size:.75rem}.designer{grid-template-columns:170px 1fr}.palette{display:grid;align-content:start;gap:6px;padding:10px;border:1px solid var(--line);background:rgba(5,10,20,.55)}.canvas{display:grid;gap:10px;max-height:70vh;overflow:auto}.designer-head{display:grid;grid-template-columns:1fr 1fr auto auto;gap:8px}.flow-node{display:grid;gap:8px;padding:12px;border:1px solid rgba(40,211,255,.35);background:rgba(40,211,255,.05)}.flow-node header{display:grid;grid-template-columns:auto 1fr auto;gap:8px;align-items:center}.node-fields{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.flow-node small{color:var(--muted)}.run-card{display:grid;gap:8px;padding:12px;border:1px solid var(--line);background:rgba(5,10,20,.55)}.run-card div:first-child{display:flex;justify-content:space-between;gap:8px}.run-card span,.run-card p,.node-run-list{margin:0;color:var(--muted);font-size:.74rem}.node-run-list{display:flex;flex-wrap:wrap;gap:7px}.node-run-list span{padding:4px 6px;border:1px solid var(--line)}@media(max-width:760px){.designer{grid-template-columns:1fr}.designer-head,.node-fields{grid-template-columns:1fr}.workflow-card{flex-direction:column}}</style>
